// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address sender, bool doSecondCall) public {
        vm.assume(sender != address(0));

        uint256 amt = 10 ether;
        vm.deal(sender, 100 ether);

        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: amt}("");
        require(ok1, "first call should succeed");

        uint256 t1 = c.pastBlockTime();

        if (doSecondCall) {
            vm.prank(sender);
            (bool ok2, ) = address(c).call{value: amt}("");

            uint256 t2 = c.pastBlockTime();

            if (ok2) {
                assertTrue(t2 > t1);
            } else {
                assertTrue(t2 == t1);
            }
        } else {
            assertTrue(t1 > 0);
        }
    }
}
